std::vector<std::pair<size_t, size_t>> collidedPairs;

    // Simple O(n²) collision detection for demonstration
    for (size_t i = 0; i < boxes.size(); ++i)
    {
        for (size_t j = i + 1; j < boxes.size(); ++j)
        {
            // Assuming BoundingBox3D has methods to get min and max points
            // and a method to check for intersection
            if (boxes[i].Intersects(boxes[j]))
            {
                collidedPairs.emplace_back(i, j);
            }
        }
    }

    return collidedPairs;

